nta.declaration:
// Map constants
const int GRID_W = 18;
const int GRID_H = 13;
const int NUM_LANES = 5;

// Typedef
typedef int[1, 3] Lives;
typedef int[0, GRID_W-1] PosX;
typedef int[0, GRID_H-1] PosY;

// Global variables
PosX frog_x = 0;
PosY frog_y = 9;
Lives lives = 3;

// Channels

template.declaration:
// Template Vehicle
clock x;                    // local clock of Vehicle     

//int lane = init_y;          // Initialization of the variable lane based on the input
                            // Note that this measurement is fixed during the execution of the TA
                            // ensuring that a vehicle stays in the same row in which is initialized 
