nta.system:
// Vehicle instantiations
// OC - OrangeCar
OC1 = Vehicle(1, 3, 4, 1);
OC2 = Vehicle(1, 3, 14, 1);

// B - Bulldozer
B1 = Vehicle(1, 10, 2, 2);
B2 = Vehicle(1, 10, 11, 2);

// GC - GreenCar
GC1 = Vehicle(1, 5, 4, 3);
GC2 = Vehicle(1, 5, 8, 3);
GC3 = Vehicle(1, 5, 12, 3);
GC4 = Vehicle(1, 5, 16, 3);

// PC - PurpleCar
PC1 = Vehicle(1, 4, 2, 4);
PC2 = Vehicle(1, 4, 10, 4);

// T - Truck
T1 = Vehicle(2, 7, 4, 5);
T2 = Vehicle(2, 7, 15, 5);

// List one or more processes to be composed into a system.
system OC1, OC2, B1, B2, GC1, GC2, GC3, GC4, PC1, PC2, T1, T2;
